const UnsavedGuard=function(){const watched=[];let beforeUnloadOn=false;function snapshot(form){const out=[];const fields=form.querySelectorAll("input, select, textarea");for(let i=0;i<fields.length;i++){const f=fields[i];if(f.type==="file"||f.disabled)continue;out.push(f.type==="checkbox"||f.type==="radio"?f.checked?"1":"0":f.value)}return out.join("\0")}function entryFor(form){for(let i=0;i<watched.length;i++)if(watched[i].form===form)return watched[i];return null}function entryDirty(e){if(!document.body.contains(e.form))return false;if(e.skipWhenHidden&&e.form.offsetParent===null)return false;if(e.forced)return true;return snapshot(e.form)!==e.clean}function anyDirty(){for(let i=0;i<watched.length;i++)if(entryDirty(watched[i]))return true;return false}function onBeforeUnload(e){e.preventDefault();e.returnValue="";return""}function syncBeforeUnload(){const want=anyDirty();if(want===beforeUnloadOn)return;if(want)window.addEventListener("beforeunload",onBeforeUnload);else window.removeEventListener("beforeunload",onBeforeUnload);beforeUnloadOn=want}function watch(form,opts){if(!form)return;let e=entryFor(form);if(!e){e={form:form,clean:"",forced:false,skipWhenHidden:!!(opts&&opts.skipWhenHidden)};watched.push(e);form.addEventListener("input",syncBeforeUnload);form.addEventListener("change",syncBeforeUnload)}e.clean=snapshot(form);e.forced=false;syncBeforeUnload()}function markSaved(form){const e=entryFor(form);if(!e)return;e.clean=snapshot(form);e.forced=false;syncBeforeUnload()}function markDirty(form){const e=entryFor(form);if(!e)return;e.forced=true;syncBeforeUnload()}function release(form){for(let i=watched.length-1;i>=0;i--){if(watched[i].form===form)watched.splice(i,1)}syncBeforeUnload()}function shouldGuardLink(a,e){if(e.defaultPrevented)return false;if(e.button!==0||e.metaKey||e.ctrlKey||e.shiftKey||e.altKey)return false;if(!a||a.hasAttribute("download")||a.target==="_blank")return false;const href=a.getAttribute("href")||"";if(!href||href.charAt(0)==="#")return false;if(/^(mailto:|tel:|javascript:|sms:|whatsapp:)/i.test(href))return false;let url;try{url=new URL(a.href,window.location.href)}catch(err){return false}if(url.origin!==window.location.origin)return false;if(url.pathname===window.location.pathname&&url.search===window.location.search&&url.hash)return false;return true}function ask(onLeave){if(document.getElementById("unsaved-dialog"))return;const overlay=document.createElement("div");overlay.id="unsaved-dialog";overlay.className="unsaved-overlay";overlay.innerHTML='<div class="unsaved-card" role="alertdialog" aria-modal="true" aria-labelledby="unsaved-title">'+'<h2 id="unsaved-title">You have not saved your changes</h2>'+"<p>If you leave this page now, what you typed will be lost.</p>"+'<button type="button" class="btn btn-primary btn-block" id="unsaved-stay">Stay and save</button>'+'<button type="button" class="btn btn-block btn-outline" id="unsaved-leave">Leave without saving</button>'+"</div>";document.body.appendChild(overlay);const close=()=>{overlay.remove();document.removeEventListener("keydown",onEsc)};const onEsc=ev=>{if(ev.key==="Escape")close()};document.getElementById("unsaved-stay").addEventListener("click",close);document.getElementById("unsaved-stay").focus();document.getElementById("unsaved-leave").addEventListener("click",()=>{close();watched.length=0;syncBeforeUnload();onLeave()});overlay.addEventListener("click",ev=>{if(ev.target===overlay)close()});document.addEventListener("keydown",onEsc)}document.addEventListener("click",e=>{if(!anyDirty())return;const a=e.target&&e.target.closest?e.target.closest("a[href]"):null;if(!shouldGuardLink(a,e))return;const href=a.href;e.preventDefault();e.stopPropagation();ask(()=>{window.location.href=href})},true);return{watch:watch,markSaved:markSaved,markDirty:markDirty,release:release,isDirty:anyDirty}}();